def generate() -> tuple[Path, Path]:
    """Generate and save both corpora to data/.

    Returns:
        Tuple of (benign_path, attacks_path).
    """
    DATA_DIR.mkdir(parents=True, exist_ok=True)

    # Build benign corpus
    benign_corpus: list[dict[str, str]] = []
    for industry, prompts in BENIGN_PROMPTS.items():
        for i, prompt in enumerate(prompts):
            benign_corpus.append({
                "id": f"{industry}-{i+1:03d}",
                "industry": industry,
                "prompt": prompt,
            })

    benign_path = DATA_DIR / "benchmark_benign.json"
    with open(benign_path, "w") as f:
        json.dump({
            "description": "500 realistic business prompts across 10 industries for false positive benchmarking",
            "total": len(benign_corpus),
            "industries": list(BENIGN_PROMPTS.keys()),
            "prompts": benign_corpus,
        }, f, indent=2)

    # Save attacks corpus
    attacks_path = DATA_DIR / "benchmark_attacks.json"
    with open(attacks_path, "w") as f:
        json.dump({
            "description": "100 attack prompts across AEGIS threat model categories",
            "total": len(ATTACK_PROMPTS),
            "categories": sorted(set(a["category"] for a in ATTACK_PROMPTS)),
            "prompts": ATTACK_PROMPTS,
        }, f, indent=2)

    print(f"Generated {len(benign_corpus)} benign prompts -> {benign_path}")
    print(f"Generated {len(ATTACK_PROMPTS)} attack prompts -> {attacks_path}")

    return benign_path, attacks_path


if __name__ == "__main__":
    generate()